MCITEM.Potions.ByID = {}
for _, definition in ipairs(MCITEM.Potions.Definitions) do
    MCITEM.Potions.ByID[definition.id] = definition
end

MCITEM.Potions.BottleTypes = {
    drinkable = { itemId = "potion", modelPrefix = "potion_" },
    splash = { itemId = "splash_potion", modelPrefix = "splash_potion_" },
    lingering = { itemId = "lingering_potion", modelPrefix = "lingering_potion_" },
}

function MCITEM.Potions.Get(potionId)
    if not isstring(potionId) then return nil end
    potionId = string.gsub(potionId, "^minecraft:", "")
    return MCITEM.Potions.ByID[potionId]
end

function MCITEM.Potions.ModelID(bottleType, potionId)
    local bottle = MCITEM.Potions.BottleTypes[bottleType]
    local potion = MCITEM.Potions.Get(potionId)
    if not bottle or not potion then return nil end
    return bottle.modelPrefix .. potion.id
end
